import { Button, Toast } from 'antd-mobile';
import { BizForm, BizFormItemInput, BizCaptchaButton } from 'mobile-more';
import { isMobile } from 'util-helpers';
import { sleep } from 'ut2';
import { useSetState } from 'rc-hooks';

async function sendCaptcha(mobile: string) {
  console.log(mobile);
  await sleep();
  return;
}

function Demo() {
  const [form] = BizForm.useForm();
  const [state, setState] = useSetState({
    loading: false,
    start: false
  });

  const handleClickCaptcha = async () => {
    try {
      await form.validateFields(['mobile']);
    } catch (err: any) {
      Toast.show({ content: err.errorFields[0].errors[0] });
      return;
    }
    setState({ loading: true });
    sendCaptcha(form.getFieldValue(['mobile'])).finally(() => {
      setState({ loading: false, start: true });
    });
  };

  return (
    <BizForm
      name="form-captcha"
      form={form}
      layout="horizontal"
      hasFeedback={false}
      requiredMarkStyle="text-optional"
      initialValues={{
        mobile: '13000000000'
      }}
      onFinish={(values) => {
        console.log(values);
      }}
      onFinishFailed={(errInfo) => {
        Toast.show({ content: errInfo.errorFields[0].errors[0] });
      }}
      footer={
        <Button type="submit" color="primary" block>
          \u767B\u5F55
        </Button>
      }
    >
      <BizFormItemInput
        name="mobile"
        label="\u624B\u673A\u53F7\u7801"
        type="number"
        maxLength={11}
        required
        extendRules={[
          {
            validator(_, value) {
              if (value && !isMobile(value)) {
                return Promise.reject('\u8BF7\u8F93\u5165\u6B63\u786E\u7684\u624B\u673A\u53F7\u7801');
              }
              return Promise.resolve();
            }
          }
        ]}
      />
      <BizFormItemInput
        name="captcha"
        label="\u77ED\u4FE1\u9A8C\u8BC1\u7801"
        extra={
          <BizCaptchaButton
            size="small"
            color="primary"
            fill="none"
            onClick={handleClickCaptcha}
            start={state.start}
            loading={state.loading}
          />
        }
        maxLength={6}
        rules={[
          {
            required: true,
            message: '\u8BF7\u8F93\u5165\u77ED\u4FE1\u9A8C\u8BC1\u7801'
          }
        ]}
      />
    </BizForm>
  );
}

export default Demo;
