import { useAsync } from 'rc-hooks';
import { SpinLoading } from 'antd-mobile';
import { BizImage, BizImageProps } from 'mobile-more';
import { setDataURLPrefix } from 'util-helpers';
import { filedownload } from '../services';

const LoadingView = (
  <div
    style={{
      height: '100%',
      width: '100%',
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center'
    }}
  >
    <SpinLoading color="primary" />
  </div>
);

interface ImageWithServiceProps extends Omit<BizImageProps, 'src'> {
  fssid?: string;
}

const ImageWithService: React.FC<ImageWithServiceProps> = ({ fssid, ...restProps }) => {
  const { data, run, loading } = useAsync(
    () =>
      filedownload({ fssid } as { fssid: string }).then((res) => setDataURLPrefix(res.data.buffer)),
    {
      autoRun: false,
      cacheKey: fssid,
      cacheTime: 30 * 60 * 1000,
      persisted: true
    }
  );

  React.useEffect(() => {
    if (fssid) {
      run();
    }
  }, [fssid, run]);

  return (
    <BizImage
      src={data}
      placeholder={LoadingView}
      fallback={loading ? LoadingView : undefined}
      {...restProps}
    />
  );
};

export default ImageWithService;
